import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import { createVoiceInput, isSpoken, VOICE_CONTEXT, type VoiceState } from "./use-voice-input";
import type { VoiceHandlers } from "./voice-recorder";

function harness({ stopWith = "spent 12.40 cash at Netto", maxSeconds = 120 } = {}) {
  const states: VoiceState[] = [];
  const finished: [string, string][] = [];
  const recording = { stop: vi.fn(async () => stopWith), cancel: vi.fn() };
  let handlers!: VoiceHandlers;
  let grant!: () => void;
  let deny!: (error: Error) => void;
  const record = vi.fn((given: VoiceHandlers) => { handlers = given; return new Promise<typeof recording>((resolve, reject) => { grant = () => resolve(recording); deny = reject; }); });
  const voice = createVoiceInput({ record, onFinish: (action, text) => finished.push([action, text]), onChange: state => states.push(state), maxSeconds, now: () => 1000 });
  return { voice, record, recording, states, finished, get handlers() { return handlers; }, grant: () => grant(), deny: (error: Error) => deny(error) };
}
const recordingNow = async (h: ReturnType<typeof harness>) => { const started = h.voice.start(); h.grant(); await started; };

beforeEach(() => vi.useFakeTimers());
afterEach(() => vi.useRealTimers());

describe("voice input state machine", () => {
  it("goes idle → starting → recording with live words and level", async () => {
    const h = harness();
    const started = h.voice.start();
    expect(h.voice.state.status).toBe("starting");
    h.grant(); await started;
    expect(h.voice.state).toMatchObject({ status: "recording", startedAt: 1000 });
    h.handlers.onText("spent 12");
    h.handlers.onLevel(0.4);
    expect(h.voice.state).toMatchObject({ text: "spent 12", level: 0.4 });
  });

  it("Send stops, waits for the final transcript and sends it", async () => {
    const h = harness();
    await recordingNow(h);
    h.handlers.onText("spent 12.40 cash");
    const sending = h.voice.send();
    expect(h.voice.state.status).toBe("finishing");
    await sending;
    expect(h.recording.stop).toHaveBeenCalledOnce();
    expect(h.finished).toEqual([["send", "spent 12.40 cash at Netto"]]);
    expect(h.voice.state).toMatchObject({ status: "idle", text: "", error: "" });
  });

  it("Done hands the transcript to the input instead of sending", async () => {
    const h = harness();
    await recordingNow(h);
    await h.voice.done();
    expect(h.finished).toEqual([["done", "spent 12.40 cash at Netto"]]);
  });

  it("falls back to the live words when the final transcript is empty or the stop fails", async () => {
    const h = harness({ stopWith: "  " });
    await recordingNow(h);
    h.handlers.onText("chips and eggs");
    await h.voice.send();
    expect(h.finished).toEqual([["send", "chips and eggs"]]);
    const failing = harness();
    failing.recording.stop.mockRejectedValueOnce(new Error("closed"));
    await recordingNow(failing);
    failing.handlers.onText("eggs");
    await failing.voice.done();
    expect(failing.finished).toEqual([["done", "eggs"]]);
  });

  it("sends nothing when nothing was heard", async () => {
    const h = harness({ stopWith: "" });
    await recordingNow(h);
    await h.voice.send();
    expect(h.finished).toEqual([]);
    expect(h.voice.state).toMatchObject({ status: "idle", error: "Didn't catch that. Try again." });
  });

  it("cancel discards the recording and ignores its late words", async () => {
    const h = harness();
    await recordingNow(h);
    h.handlers.onText("never mind");
    h.voice.cancel();
    expect(h.recording.cancel).toHaveBeenCalledOnce();
    expect(h.voice.state).toMatchObject({ status: "idle", text: "" });
    h.handlers.onText("late words");
    await h.voice.send();
    expect(h.voice.state.text).toBe("");
    expect(h.finished).toEqual([]);
  });

  it("cancel while the mic is starting releases it once granted", async () => {
    const h = harness();
    const started = h.voice.start();
    h.voice.cancel();
    h.grant(); await started;
    expect(h.recording.cancel).toHaveBeenCalledOnce();
    expect(h.voice.state.status).toBe("idle");
  });

  it("cancel while finishing drops the transcript", async () => {
    const h = harness();
    await recordingNow(h);
    const sending = h.voice.send();
    h.voice.cancel();
    await sending;
    expect(h.finished).toEqual([]);
  });

  it("ignores Send and Done unless recording, and a second start while busy", async () => {
    const h = harness();
    await h.voice.send(); await h.voice.done();
    const started = h.voice.start();
    void h.voice.start();
    expect(h.record).toHaveBeenCalledOnce();
    h.grant(); await started;
    expect(h.finished).toEqual([]);
  });

  it("shows a denied or unsupported mic as an error and returns to idle", async () => {
    const h = harness();
    const started = h.voice.start();
    h.deny(new Error("Microphone access is blocked. Allow it in your browser settings to talk to Moneo."));
    await started;
    expect(h.voice.state).toMatchObject({ status: "idle", error: "Microphone access is blocked. Allow it in your browser settings to talk to Moneo." });
    h.voice.cancel();
    expect(h.voice.state.error).toBe("");
  });

  it("a dropped connection keeps what was heard in the input", async () => {
    const h = harness();
    await recordingNow(h);
    h.handlers.onText("spent 5 at");
    h.handlers.onError(new Error("Lost the connection to voice transcription."));
    expect(h.recording.cancel).toHaveBeenCalledOnce();
    expect(h.finished).toEqual([["done", "spent 5 at"]]);
    expect(h.voice.state).toMatchObject({ status: "idle", error: "Lost the connection to voice transcription." });
  });

  it("stops at the length limit as Done", async () => {
    const h = harness({ maxSeconds: 120 });
    await recordingNow(h);
    await vi.advanceTimersByTimeAsync(119_000);
    expect(h.voice.state.status).toBe("recording");
    await vi.advanceTimersByTimeAsync(1_000);
    expect(h.finished).toEqual([["done", "spent 12.40 cash at Netto"]]);
  });
});

it("marks spoken messages through their context only", () => {
  expect(isSpoken(VOICE_CONTEXT)).toBe(true);
  expect(isSpoken({ path: "/" })).toBe(false);
  expect(isSpoken(null)).toBe(false);
});

import { afterEach, beforeEach, expect, it, vi } from "vitest";
import { level, pcm16Base64, startVoiceRecording } from "./voice-recorder";

class FakeSocket {
  static CONNECTING = 0; static OPEN = 1; static CLOSING = 2; static CLOSED = 3;
  static last: FakeSocket;
  readyState = FakeSocket.CONNECTING;
  sent: { type: string; audio?: string }[] = [];
  onopen: (() => void) | null = null; onmessage: ((event: { data: string }) => void) | null = null;
  onerror: (() => void) | null = null; onclose: (() => void) | null = null;
  constructor(public url: string, public protocols: string[]) { FakeSocket.last = this; }
  send(message: string) { this.sent.push(JSON.parse(message)); }
  close() { this.readyState = FakeSocket.CLOSED; }
  open() { this.readyState = FakeSocket.OPEN; this.onopen?.(); }
  emit(event: object) { this.onmessage?.({ data: JSON.stringify(event) }); }
}
const audio = vi.hoisted(() => ({ state: "running", closed: 0, processor: null as null | { onaudioprocess: ((event: unknown) => void) | null } }));
class FakeAudioContext {
  sampleRate = 48000; destination = {};
  get state() { return audio.closed ? "closed" : audio.state; }
  resume() { return Promise.resolve(); }
  close() { audio.closed++; return Promise.resolve(); }
  createMediaStreamSource() { return { connect: vi.fn() }; }
  createGain() { return { gain: { value: 1 }, connect: vi.fn() }; }
  createScriptProcessor() { audio.processor = { onaudioprocess: null }; return Object.assign(audio.processor, { connect: vi.fn() }); }
}
const track = { stop: vi.fn() };
const getUserMedia = vi.fn();
const fetchMock = vi.fn();
const handlers = () => ({ onText: vi.fn(), onLevel: vi.fn(), onError: vi.fn() });
const speak = (value = 0.5) => audio.processor!.onaudioprocess!({ inputBuffer: { getChannelData: () => new Float32Array(480).fill(value) } });

beforeEach(() => {
  audio.state = "running"; audio.closed = 0; audio.processor = null; track.stop.mockClear();
  getUserMedia.mockResolvedValue({ getTracks: () => [track] });
  fetchMock.mockResolvedValue(Response.json({ token: "ek_test", url: "wss://api.openai.com/v1/realtime?intent=transcription" }));
  vi.stubGlobal("window", { AudioContext: FakeAudioContext, WebSocket: FakeSocket });
  vi.stubGlobal("navigator", { mediaDevices: { getUserMedia } });
  vi.stubGlobal("WebSocket", FakeSocket);
  vi.stubGlobal("AudioContext", FakeAudioContext);
  vi.stubGlobal("fetch", fetchMock);
});
afterEach(() => vi.unstubAllGlobals());

it("converts 48 kHz float samples to 24 kHz 16-bit PCM", () => {
  const pcm = Buffer.from(pcm16Base64(new Float32Array([0, 0, 1, 1, -1, -1, 2, 2]), 48000), "base64");
  expect([...new Int16Array(pcm.buffer, pcm.byteOffset, pcm.length / 2)]).toEqual([0, 32767, -32767, 32767]);
  expect(level(new Float32Array(4))).toBe(0);
  expect(level(new Float32Array(4).fill(1))).toBe(1);
});

it("streams audio with the short-lived secret and shows words as they arrive", async () => {
  const events = handlers();
  const recording = await startVoiceRecording(events);
  const socket = FakeSocket.last;
  expect(fetchMock).toHaveBeenCalledWith("/api/voice/session", expect.objectContaining({ method: "POST" }));
  expect(socket.protocols).toEqual(["realtime", "openai-insecure-api-key.ek_test"]);
  speak();
  expect(events.onLevel).toHaveBeenCalledWith(1);
  socket.open();
  speak();
  expect(socket.sent.map(message => message.type)).toEqual(["input_audio_buffer.append", "input_audio_buffer.append"]);
  socket.emit({ type: "conversation.item.input_audio_transcription.delta", item_id: "a", delta: "Spent" });
  socket.emit({ type: "conversation.item.input_audio_transcription.delta", item_id: "a", delta: " twelve" });
  expect(events.onText).toHaveBeenLastCalledWith("Spent twelve");
  const stopped = recording.stop();
  expect(socket.sent.at(-1)).toEqual({ type: "input_audio_buffer.commit" });
  expect(track.stop).toHaveBeenCalled();
  socket.emit({ type: "conversation.item.input_audio_transcription.completed", item_id: "a", transcript: "Spent 12.40 at Netto." });
  expect(await stopped).toBe("Spent 12.40 at Netto.");
  expect(socket.readyState).toBe(FakeSocket.CLOSED);
  expect(audio.closed).toBe(1);
});

it("cancel closes the mic and the connection without waiting", async () => {
  const recording = await startVoiceRecording(handlers());
  FakeSocket.last.open();
  recording.cancel();
  expect(track.stop).toHaveBeenCalled();
  expect(FakeSocket.last.readyState).toBe(FakeSocket.CLOSED);
  expect(FakeSocket.last.sent).toEqual([]);
});

it("reports a dropped connection while recording", async () => {
  const events = handlers();
  await startVoiceRecording(events);
  FakeSocket.last.open();
  FakeSocket.last.onclose?.();
  expect(events.onError).toHaveBeenCalledWith(new Error("Lost the connection to voice transcription."));
});

it("explains a blocked microphone and never asks for a session", async () => {
  getUserMedia.mockRejectedValue(new DOMException("denied", "NotAllowedError"));
  await expect(startVoiceRecording(handlers())).rejects.toThrow("Microphone access is blocked");
  expect(fetchMock).not.toHaveBeenCalled();
  expect(audio.closed).toBe(1);
});

it("asks for a tap when the browser keeps audio suspended", async () => {
  vi.useFakeTimers();
  audio.state = "suspended";
  const started = startVoiceRecording(handlers());
  const failed = expect(started).rejects.toThrow("Tap the mic to start recording.");
  await vi.advanceTimersByTimeAsync(1000);
  await failed;
  expect(track.stop).toHaveBeenCalled();
  vi.useRealTimers();
});

it("passes on the session route's error and releases the mic", async () => {
  fetchMock.mockResolvedValue(Response.json({ error: "Voice input is not configured" }, { status: 503 }));
  await expect(startVoiceRecording(handlers())).rejects.toThrow("Voice input is not configured");
  expect(track.stop).toHaveBeenCalled();
});

it("says so when the browser has no microphone API", async () => {
  vi.stubGlobal("navigator", {});
  await expect(startVoiceRecording(handlers())).rejects.toThrow("Voice input isn't supported in this browser.");
});
